param([string]$GameRoot='', [switch]$HubConfirmed, [switch]$NoPause)
$ErrorActionPreference='Stop';. (Join-Path $PSScriptRoot '..\Modules\OwnedModFiles.ps1');$id='kcd1vr';$receipt=Join-Path $PSScriptRoot '.installed_path';$begin='-- BEGIN KCD1VR MANAGED SETTINGS';$end='-- END KCD1VR MANAGED SETTINGS'
function Finish([int]$c){if(-not $NoPause){Read-Host 'Press Enter to exit'|Out-Null};exit $c};function Test-Root([string]$p){$p -and (Test-Path (Join-Path $p 'Bin\Win64\KingdomCome.exe')) -and (Test-Path (Join-Path $p ".pcvrhub_${id}_ownership.csv"))}
if(-not(Test-Root $GameRoot) -and (Test-Path $receipt)){$GameRoot=([IO.File]::ReadAllText($receipt)).Trim().Trim('"')};if(-not(Test-Root $GameRoot)){Write-Host '  No Hub-owned KCD1VR installation was found.' -ForegroundColor Yellow;Finish 0};if(Get-Process -Name 'KingdomCome' -ErrorAction SilentlyContinue){Write-Host '  [XX] Close the game first.' -ForegroundColor Red;Finish 1};if(-not $HubConfirmed -and (Read-Host "Remove Hub-owned KCD1VR files from '$GameRoot'? Type REMOVE") -cne 'REMOVE'){Finish 0}
$cfg=Join-Path $GameRoot 'user.cfg';if(Test-Path $cfg){$text=[IO.File]::ReadAllText($cfg);$pattern='(?ms)^\s*'+[regex]::Escape($begin)+'.*?'+[regex]::Escape($end)+'\s*(?:\r?\n)?';$clean=([regex]::Replace($text,$pattern,'')).TrimEnd();if($clean){[IO.File]::WriteAllText($cfg,$clean+"`r`n",[Text.UTF8Encoding]::new($false))}else{Remove-Item $cfg -Force}}
$r=Uninstall-OwnedModPayload -GameRoot $GameRoot -Identity $id;if($r.Preserved -eq 0){Remove-Item (Join-Path $GameRoot '.pcvrhub_version') -Force -ErrorAction SilentlyContinue;Remove-Item $receipt -Force -ErrorAction SilentlyContinue};Write-Host "  [OK] Removed $($r.Removed), restored $($r.Restored), preserved $($r.Preserved)." -ForegroundColor Green;Write-Host '  The game, saves and unrelated user.cfg settings remain installed.' -ForegroundColor Gray;Finish 0
